import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\nimport 'providers/device_state_provider.dart';\nimport 'screens/control_dashboard.dart';\n\nvoid main() {\n  runApp(\n    MultiProvider(\n      providers: [\n        ChangeNotifierProvider(create: (_) => DeviceStateProvider()),\n      ],\n      child: const SmartBulbApp(),\n    ),\n  );\n}\n\nclass SmartBulbApp extends StatelessWidget {\n  const SmartBulbApp({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      title: 'Matter RGB Bulb',\n      theme: ThemeData(\n        brightness: Brightness.dark,\n        primarySwatch: Colors.deepPurple,\n      ),\n      // Pre-filled with fake ID for demonstration\n      home: const ControlDashboard(deviceId: "MATTER-NODE-123456"), \n    );\n  }\n}\n
